-- Migration 001 : première base autonome du Bas de laine.
BEGIN;
   CREATE TABLE accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('bank','card')),is_main INTEGER NOT NULL DEFAULT 0,opening_card_cents INTEGER NOT NULL DEFAULT 0 CHECK(opening_card_cents>=0),source_key TEXT UNIQUE,source_hash TEXT,dirty INTEGER NOT NULL DEFAULT 0);
   CREATE UNIQUE INDEX one_main_account ON accounts(is_main) WHERE is_main=1;
   CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,limit_cents INTEGER CHECK(limit_cents>=0),period TEXT CHECK(period IN ('weekly','monthly')),renewal_day INTEGER,starts_on TEXT,active INTEGER NOT NULL DEFAULT 1,source_key TEXT UNIQUE,source_hash TEXT,dirty INTEGER NOT NULL DEFAULT 0);
   CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,seq INTEGER NOT NULL UNIQUE,account_id INTEGER NOT NULL REFERENCES accounts(id),category_id INTEGER REFERENCES categories(id),description TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents!=0),date TEXT NOT NULL,period_on TEXT,included INTEGER NOT NULL DEFAULT 0,settled_cents INTEGER NOT NULL DEFAULT 0 CHECK(settled_cents>=0),source_key TEXT UNIQUE,source_hash TEXT,dirty INTEGER NOT NULL DEFAULT 0);
   CREATE TABLE transfers(id INTEGER PRIMARY KEY AUTOINCREMENT,seq INTEGER NOT NULL UNIQUE,from_account_id INTEGER NOT NULL REFERENCES accounts(id),to_account_id INTEGER NOT NULL REFERENCES accounts(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),date TEXT NOT NULL,description TEXT NOT NULL,included INTEGER NOT NULL DEFAULT 0,source_key TEXT UNIQUE,source_hash TEXT,dirty INTEGER NOT NULL DEFAULT 0,CHECK(from_account_id!=to_account_id));
   CREATE TABLE recurrences(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('income','expense','transfer')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),account_id INTEGER NOT NULL REFERENCES accounts(id),to_account_id INTEGER REFERENCES accounts(id),category_id INTEGER REFERENCES categories(id),start_on TEXT NOT NULL,frequency TEXT NOT NULL,day_adjust TEXT NOT NULL DEFAULT 'none',one_time INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,source_key TEXT UNIQUE,source_hash TEXT,dirty INTEGER NOT NULL DEFAULT 0);
   CREATE TABLE occurrence_states(rule_id INTEGER NOT NULL REFERENCES recurrences(id),original_on TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('paid','postponed','cancelled')),postponed_on TEXT,amount_cents INTEGER,transaction_id INTEGER REFERENCES transactions(id),transfer_id INTEGER REFERENCES transfers(id),PRIMARY KEY(rule_id,original_on));
   CREATE TABLE checkpoints(id INTEGER PRIMARY KEY AUTOINCREMENT,seq INTEGER NOT NULL UNIQUE,account_id INTEGER NOT NULL REFERENCES accounts(id),amount_cents INTEGER NOT NULL,date TEXT NOT NULL,difference_cents INTEGER NOT NULL DEFAULT 0);
   CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
   INSERT INTO settings VALUES('sequence','0');
   PRAGMA user_version=1; COMMIT;
